head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isFirstLoad = false;
scwin.isFirstLoad = false;
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar, dts_ElwInst); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.

            cmb_ISUR_CD.setSelectedIndex(0);
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값

        }

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.search();
            scwin.isFirstLoad = true;
        } else {
            await scwin.newOnload(); // 신규작성시 호출

        }
        $c.libRoundPanel.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05910.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05910.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05910.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_MktactEnforceDd, false);
        }
        cmb_ISUR_CD.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "MERGED_MERGE_ISUR_CD");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05910.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no !== "" && scwin.isFirstLoad) {
            // 수정모드에선, 처음 조회때 1회만 실행됨.
            scwin.isFirstLoad = false;
        } else {
            scwin.changeIsuNmByBatch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05910.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05910.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_MktactEnforceDd_onclick
 * @description img_MktactEnforceDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MktactEnforceDd_onclick = function() {
    try {
        popUpCalendar2(edt_MktactEnforceDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05910.img_MktactEnforceDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_ISUR_CD_onselchange2
 * @description cmb ISUR CD onselchange2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_onselchange2 = async function() {
    try {
        if (cmb_ISUR_CD.getSelectedIndex() !== 0) {
            await scwin.getIsuCd();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05910.cmb_ISUR_CD_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_ISUR_CD_OnSelected
 * @description cmb ISUR CD On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ISUR_CD_OnSelected = function() {

};

/**
 * @method
 * @name grd_isu_onexit
 * @description grd_isu onexit 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} olddata olddata
 * @returns {void}
 * @hidden N
 */
scwin.grd_isu_onexit = function(row, colid, olddata) {
    try {
        // alert('grd_isu.OnExit('+row+','+ colid+','+ olddata+')');
        dts_Isu.setCellData(row, "AFCHG_ISU_ENG_ABBRV2", dts_Isu.getCellData(row, colid));
        scwin.setIsuNm(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05910.grd_isu_onexit" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "&SCREN_ID=" + "ULDSTF05910.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/Listing.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/Listing.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    url += "&SCREN_ID=" + "ULDSTF05910.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Mst_Info",
        action : "/Listing.do",
        ref : "",
        target : "dts_Mst_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.stf.copyDataSet(dts_Mst_Info, dts_Mst);
};

/**
 * @method
 * @name getIsuCd
 * @description get Isu Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsuCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_Mst_Info",
        action : "/Listing.do",
        ref : "",
        target : "dts_Mst_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Mst.setCellData(dts_Mst.getRowPosition(), "AFCHG_COM_NM", dts_Mst_Info.getCellData(dts_Mst_Info.getRowPosition(), "BFCHG_COM_NM"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "AFCHG_COM_ABBRV", dts_Mst_Info.getCellData(dts_Mst_Info.getRowPosition(), "BFCHG_COM_ABBRV"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "AFCHG_COM_ENG_NM", dts_Mst_Info.getCellData(dts_Mst_Info.getRowPosition(), "BFCHG_COM_ENG_NM"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "AFCHG_COM_ENG_ABBRV", dts_Mst_Info.getCellData(dts_Mst_Info.getRowPosition(), "BFCHG_COM_ENG_ABBRV"));
};

/**
 * @method
 * @name saveTrs
 * @description 매매거래정지종목은 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    grd_isu.redraw = false;
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }
    grd_isu.redraw = true;
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MERGED_MERGE_ISUR_CD", cmb_ISUR_CD.BindColVal);
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_146 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_CHGLIST_ISU_MGR_CHG
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/Listing.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name changeIsuNmByBatch
 * @description change Isu Nm By Batch 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeIsuNmByBatch = function() {
    grd_isu.redraw = false;
    let ELW_ISU_CHG_TP_CD = "";
    dts_Isu.setBroadcast(false);
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        ELW_ISU_CHG_TP_CD = dts_Isu.getCellData(i, "ELW_ISU_CHG_TP_CD");
        if (ELW_ISU_CHG_TP_CD === '3') {
            dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV3", dts_Mst.getCellData(dts_Mst.getRowPosition(), "BFCHG_ULY_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV3", dts_Mst.getCellData(dts_Mst.getRowPosition(), "BFCHG_ULY_ENG_NM"));
        } else if (ELW_ISU_CHG_TP_CD === '2') {
            dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV1", dts_Mst.getCellData(dts_Mst.getRowPosition(), "BFCHG_ELW_ISUR_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV1", dts_Mst.getCellData(dts_Mst.getRowPosition(), "BFCHG_ELW_ISUR_ENG_NM"));
            // dts_Isu.NameString(i, "AFCHG_ISU_ABBRV2")               = "" ;
            // dts_Isu.NameString(i, "AFCHG_ISU_ENG_ABBRV2")        = "" ;

        }
        scwin.setIsuNm(i);
    }
    dts_Isu.setBroadcast(true, true);
    grd_isu.redraw = true;
    return true;
};

/**
 * @method
 * @name setIsuNm
 * @description set Isu Nm 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setIsuNm = function(row) {
    let ELW_ISU_CHG_TP_CD = ELW_ISU_CHG_TP_CD = dts_Isu.getCellData(row, "ELW_ISU_CHG_TP_CD");
    if (ELW_ISU_CHG_TP_CD === '3') {
        dts_Isu.setCellData(row, "AFCHG_ISU_NM", dts_Isu.getCellData(row, "BFCHG_ISU_NM"));
        dts_Isu.setCellData(row, "AFCHG_ISU_ENG_NM", dts_Isu.getCellData(row, "BFCHG_ISU_ENG_NM"));
    } else if (ELW_ISU_CHG_TP_CD === '2' || ELW_ISU_CHG_TP_CD === '1') {
        if (dts_Isu.getCellData(row, "AFCHG_ISU_ABBRV2") === "") {
            dts_Isu.setCellData(row, "AFCHG_ISU_NM", "");
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            dts_Isu.setCellData(row, "AFCHG_ISU_NM", /*ORG SRC: dts_Isu.setNameString(row, "AFCHG_ISU_NM", dts_Isu.NameString(row, "AFCHG_ISU_NM") = );*/ X = X);
            dts_Isu.getCellData(row, "AFCHG_ISU_ABBRV2") + "호";
        }
        if (dts_Isu.getCellData(row, "AFCHG_ISU_ENG_ABBRV2") === "") {
            dts_Isu.setCellData(row, "AFCHG_ISU_ENG_NM", "");
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            dts_Isu.setCellData(row, "AFCHG_ISU_ENG_NM", /*ORG SRC: dts_Isu.setNameString(row, "AFCHG_ISU_ENG_NM", dts_Isu.NameString(row, "AFCHG_ISU_ENG_NM") = );*/ X = X);
            dts_Isu.getCellData(row, "AFCHG_ISU_ENG_ABBRV2");
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (!$c.lc.checkDdTm("DD", edt_MktactEnforceDd, "변경상장", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_ChgRsnContn, "흡수합병사유")) return false;
    if (!$c.stf.checkMaxLength(txb_ChgRsnContn, 2000, "흡수합병사유")) return false;
    if (cmb_ISUR_CD.getSelectedIndex() === 0) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0017", ""));
        cmb_ISUR_CD.focus();
        return;
    }
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        if (dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV1") === "" || dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV2") === "" ||
            dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV3") === "" || dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV4") === "" ||
            dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV1") === "" || dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV2") === "" ||
            dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV3") === "" || dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV4") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0018", ""));
            return;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
